query:
NODE VALUE `out_degree` SumAgg<INT64> = 0
TABLE `degrees` {`id` STRING, `degree` INT64}

MATCH (`src`:`player`)-[`edge`:`follow`]->(`dst`:`player`)
PER PATH {
  SET `src`.@`out_degree` += 1
}

MATCH (`p`:`player`)
PER NODE (`p`) {
  EXPORT `p`.`id` AS `id`, coalesce(`p`.@`out_degree`, 0) AS `degree` INTO `degrees`
}

FOR `row` IN `degrees`
RETURN `row`.`id` AS `id`, `row`.`degree` AS `degree`
